-- ============================================================
-- SEED EXT 6: Módulo 20 — Academic Connectors (ex 251-300)
-- Blocos 59-64 | 50 exercícios
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'academic-connectors';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo academic-connectors não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 59: Advanced concession and contrast connectors (8 ex)
  (cid,59,251,'multiple_choice','Which connector BEST introduces a concession that the writer then counters?','Notwithstanding the evidence for X, the dominant trend points toward Y.','["Furthermore, the evidence for X points toward Y.","Notwithstanding the evidence for X, the dominant trend points toward Y.","Consequently, the evidence for X points toward Y.","In other words, the evidence for X points toward Y."]','''Notwithstanding'' = despite / in spite of; signals concession the writer will then qualify or counter. ''Furthermore'' (addition), ''consequently'' (result), ''in other words'' (restatement) do not fit.','hard'),
  (cid,59,252,'gap_fill','_____ (Albeit) the sample size was limited, the results _____ (be) consistent with those of larger studies, _____ (suggest/gerund) that the core finding is _____ (robust).','Albeit / were / suggesting / robust',NULL,'''Albeit'' = although/even though (formal); triggers no inversion; ''suggesting'' = participial clause adding inference.','hard'),
  (cid,59,253,'gap_fill','The policy achieved its primary objective; _____ (nevertheless), several _____ (unintend → noun) consequences _____ (emerge/past), _____ (raise/gerund) questions about the adequacy of the original _____ (design).','nevertheless / unintended / emerged / raising / design',NULL,'''Nevertheless'' = despite what was just said; semicolon before it; ''unintended consequences''; participial clause extends the idea.','medium'),
  (cid,59,254,'multiple_choice','Identify the sentence that uses ''whereas'' correctly to show contrast.','Rural areas experienced population decline, whereas urban centers continued to grow rapidly.','["Rural areas experienced population decline, whereas they also grew.","Rural areas experienced population decline, whereas urban centers continued to grow rapidly.","Rural areas experienced population decline. Whereas urban centers grew.","Whereas experienced population decline, rural areas grew."]','Option B: ''whereas'' links two contrasting clauses in a single sentence; it cannot begin a standalone sentence or link identical content.','medium'),
  (cid,59,255,'gap_fill','The intervention was _____ (cost-effective), _____ (at/least) in the _____ (short/term); _____ (in/the/long/run), _____ (however), the _____ (sustain/adjective) of its _____ (effect) _____ (remain/past) uncertain.','cost-effective / at least / short term / in the long run / however / sustainability / effects / remained',NULL,'''At least'' qualifies scope; ''in the long run'' = temporal contrast; ''however'' = adversative connector after semicolon.','hard'),
  (cid,59,256,'gap_fill','_____ (On/the/one/hand), increased trade _____ (generate/past) significant economic growth; _____ (on/the/other/hand), it _____ (expose/past) domestic industries to _____ (competitive/noun) pressures that _____ (prove/past) _____ (difficult) to _____ (manage).','On the one hand / generated / on the other hand / exposed / competitive / pressures / proved / difficult / manage',NULL,'''On the one hand...on the other hand'' = standard contrast pair; both clauses parallel in structure.','medium'),
  (cid,59,257,'gap_fill','The theory is _____ (elegant/adverb) simple, _____ (yet) its _____ (implication) are _____ (profound) and _____ (far-reaching), _____ (touch/gerund) on questions that have _____ (preoccupy/past) philosophers for _____ (century).','elegantly / yet / implications / profound / far-reaching / touching / preoccupied / centuries',NULL,'''Yet'' = formal adversative (= but); ''elegantly simple'' = adverb + adjective; participial clause adds elaboration.','medium'),
  (cid,59,258,'multiple_choice','Which sentence uses ''by contrast'' correctly?','Experimental studies offer high internal validity. By contrast, observational studies are better suited to capturing real-world complexity.','["Experimental studies offer high validity by contrast observational studies capture complexity.","Experimental studies offer high internal validity. By contrast, observational studies are better suited to capturing real-world complexity.","By contrast experimental studies offer validity while observational studies have complexity.","Experimental studies by contrast offer high validity than observational studies."]','Option B: ''By contrast'' begins a new sentence after a full stop; preceded by comma; introduces the contrasting idea.','easy'),

  -- BLOCK 60: Cause-effect and result connectors (8 ex)
  (cid,60,259,'multiple_choice','Which connector signals a logical consequence most formally?','The intervention reduced costs; consequently, it was adopted at scale.','["The intervention reduced costs; however, it was adopted at scale.","The intervention reduced costs; therefore, it was adopted at scale.","The intervention reduced costs; consequently, it was adopted at scale.","The intervention reduced costs; furthermore, it was adopted at scale."]','Options B and C are both correct (''therefore'' and ''consequently'' both signal result). ''Consequently'' is slightly more formal; ''however'' (contrast) and ''furthermore'' (addition) do not signal result.','medium'),
  (cid,60,260,'gap_fill','The new regulation _____ (impose/past) significant compliance costs on small businesses, _____ (thereby) _____ (create/gerund) a barrier to _____ (entry) that _____ (disproportionately) _____ (affect/past) _____ (new/noun/entrant).','imposed / thereby / creating / entry / disproportionately / affected / new entrants',NULL,'''Thereby + gerund'' = formal connector showing mechanism of consequence; ''disproportionately affected new entrants.''','hard'),
  (cid,60,261,'gap_fill','_____ (As/a/result/of) the _____ (rapid) _____ (expand → noun) of _____ (urbanization), _____ (pressure) on _____ (water/resource) _____ (have/intensify) _____ (substantially/adverb) in _____ (many) _____ (developing) _____ (economy).','As a result of / rapid / expansion / urbanization / pressure / water resources / have intensified / substantially / many / developing / economies',NULL,'''As a result of + noun phrase'' = prepositional causal connector; triggers normal word order.','medium'),
  (cid,60,262,'gap_fill','The study found that increased investment in early education _____ (lead/past) to _____ (measurable) _____ (improve → noun) in _____ (long-term) _____ (outcome), _____ (hence) the _____ (author''s) _____ (recommend → noun) for _____ (substantial) _____ (policy) _____ (reform).','led / measurable / improvements / long-term / outcomes / hence / author''s / recommendation / substantial / policy / reform',NULL,'''Hence'' = therefore/consequently (formal); used here to introduce an implication or recommendation from the finding.','hard'),
  (cid,60,263,'multiple_choice','Which sentence uses ''thus'' correctly in academic writing?','The data were insufficient; thus, no causal claims can be made.','["The data were insufficient thus no causal claims can be made.","Thus the data were insufficient, no causal claims can be made.","The data were insufficient; thus, no causal claims can be made.","The data were insufficient, thus no causal claims can be made."]','Option C: ''thus'' after semicolon with comma = correct punctuation for a conjunctive adverb. Option D (comma splice) is acceptable in some styles but less formal.','medium'),
  (cid,60,264,'gap_fill','Poor governance _____ (lead) to _____ (weak) _____ (institution), which _____ (in/turn) _____ (undermine) _____ _____ _____ (economic/growth/prospect), _____ (create/gerund) a _____ (vicious) _____ (cycle) that is _____ (difficult) to _____ (break).','leads / weak / institutions / in turn / undermines / economic growth prospects / creating / vicious / cycle / difficult / break',NULL,'''In turn'' = sequencing the causal chain; ''creating a vicious cycle'' = participial clause naming the result.','hard'),
  (cid,60,265,'gap_fill','The failure of previous _____ (reform) _____ (effort) can be _____ (attribute/passive) to a _____ (lack) of _____ (political) _____ (will); _____ (for/this/reason), the _____ (current) _____ _____ (proposal/must/be) _____ (accompany/passive) by credible _____ (commitment/mechanism).','reform efforts / be attributed / lack / political / will / for this reason / current / proposal must be / accompanied / commitment mechanisms',NULL,'''For this reason'' = formal causal connector (= therefore); draws explicit connection between cause and prescription.','hard'),
  (cid,60,266,'multiple_choice','Which connector best completes: ''The sample was too small _____ the findings to be generalized.''?','for','["so that","in order that","for","despite"]','''For + noun phrase + to-infinitive'' = purpose/result structure: ''too small for the findings to be generalized'' = standard result construction.','medium'),

  -- BLOCK 61: Enumeration, addition and emphasis connectors (8 ex)
  (cid,61,267,'gap_fill','_____ (In/the/first/place), the policy _____ (lack/past) adequate _____ (fund); _____ (second), it _____ (fail/past) to _____ (address) the _____ (structural) _____ (cause) of the _____ (problem); _____ (finally), it _____ (generate/past) _____ (significant) _____ _____ (political/opposition).','In the first place / lacked / funding / second / failed / address / structural / causes / problem / finally / generated / significant / political opposition',NULL,'''In the first place / second / finally'' = formal enumeration sequence; maintains parallel grammatical structure.','medium'),
  (cid,61,268,'gap_fill','The reform _____ (aim/past) to improve _____ (efficiency), _____ (enhance) _____ (transparency), and _____ (above/all) _____ (restore) public _____ (confidence) in _____ _____ (institution).','aimed / efficiency / enhance / transparency / above all / restore / confidence / institutions',NULL,'''Above all'' = emphatic addition indicating the most important item in a list.','easy'),
  (cid,61,269,'multiple_choice','Which sentence uses ''moreover'' correctly?','The intervention was cost-effective. Moreover, it produced results faster than anticipated.','["The intervention was cost-effective. Moreover, it did not produce results.","The intervention was cost-effective. Moreover, it produced results faster than anticipated.","Moreover the intervention, it was cost-effective and produced results.","The intervention was cost-effective, moreover produced results."]','Option B: ''Moreover'' begins a new sentence after a full stop, adding a further supporting point in the same direction.','easy'),
  (cid,61,270,'gap_fill','_____ (Not only) _____ (did/the/initiative/reduce/costs), _____ (but/it/also) _____ (significantly/improve/past) _____ (coordination) among _____ (stakeholder). _____ (Furthermore), _____ (participant) _____ (report/past) _____ _____ (high/level) of _____ (satisfaction).','Not only did the initiative reduce costs / but it also / significantly improved / coordination / stakeholders / Furthermore / participants / reported / high levels / satisfaction',NULL,'''Not only...but also'' = emphatic addition; ''Furthermore'' = additive connector starting new sentence.','medium'),
  (cid,61,271,'gap_fill','The evidence _____ (point) strongly toward a _____ (structural) _____ (explanation). _____ (In/addition), _____ (recent) _____ (data) from _____ (comparable) _____ _____ _____ (case/lend/further) _____ (support) to this _____ (interpretation).','points / structural / explanation / In addition / recent / data / comparable / cases lend further / support / interpretation',NULL,'''In addition'' = additive connector; ''data from comparable cases lend support'' = subject-verb agreement with plural ''data.''','medium'),
  (cid,61,272,'gap_fill','The reform _____ (address/past) _____ (several) _____ (critical) _____ (issue), among _____ (which) _____ (be) the lack of _____ (accountability), the _____ (absence) of _____ _____ (transparent/process), and the _____ (inadequate/noun) of existing _____ (oversight) _____ (mechanism).','addressed / several / critical / issues / which / were / accountability / absence / transparent processes / inadequacy / oversight / mechanisms',NULL,'''Among which were'' = formal enumeration with relative clause; lists three parallel noun phrases.','hard'),
  (cid,61,273,'multiple_choice','Which sentence uses ''in particular'' correctly?','The data revealed several patterns. In particular, the correlation between governance quality and economic performance was statistically robust.','["In particular the data revealed several patterns and correlations.","The data revealed several patterns. In particular, the correlation between governance quality and economic performance was statistically robust.","The data revealed, in particular, several patterns.","In particular, the data revealed patterns. The correlation was robust."]','Option B: ''In particular'' begins a new sentence, introducing the most significant or specific example from what was just said.','easy'),
  (cid,61,274,'gap_fill','The _____ (benefit) of the program _____ (extend) _____ (well/beyond) the _____ (immediate) _____ _____ _____ (target/population). _____ (Indeed), _____ (analysis) _____ _____ _____ _____ (suggest/that/the/spillover) _____ (effect) _____ (may/exceed) the _____ (direct) _____ (impact) _____ (in/some/context).','benefits / extend / well beyond / immediate / target population / Indeed / analysis / suggests that the spillover / effects / may exceed / direct / impact / in some contexts',NULL,'''Well beyond'' = emphatic scope extension; ''Indeed'' = emphatic affirmation and expansion of previous claim.','hard'),

  -- BLOCK 62: TOEFL Speaking — connectors in spoken academic English (8 ex)
  (cid,62,275,'production','[TOEFL Speaking — 45s] Summarize a reading on public health using at least five different academic connectors.','',NULL,'The reading argues that public health systems in developed countries face mounting pressure from an aging population and rising rates of chronic disease. In the first place, the reading contends that preventive medicine receives insufficient funding relative to acute care, despite evidence that prevention is considerably more cost-effective in the long run. Furthermore, the author suggests that health inequalities between income groups have widened over the past two decades, notwithstanding significant increases in total health expenditure. Consequently, the reading calls for a fundamental reorientation of health policy priorities — one that moves resources upstream toward prevention and addresses the social determinants of health rather than simply treating their consequences. Nevertheless, the author acknowledges that such a reorientation faces significant political obstacles.','hard'),
  (cid,62,276,'production','[TOEFL Speaking — 45s] A professor challenges the reading on public health. Use connectors to contrast both positions.','',NULL,'The professor challenges the reading on several grounds. While the reading argues that preventive medicine is underfunded relative to its effectiveness, the professor contends that the evidence on cost-effectiveness is more mixed than the reading acknowledges. Furthermore, she argues that the comparison between prevention and acute care is complicated by the long time horizons involved in measuring preventive outcomes — a methodological issue that, in her view, the reading glosses over. By contrast, the professor is more sympathetic to the reading''s claim about health inequalities, suggesting that the evidence here is robust and that the policy implications are clear. Nevertheless, she maintains that the reading''s prescriptions are too general to be actionable without more specific analysis of which interventions, in which contexts, are most likely to reduce inequalities at acceptable cost.','hard'),
  (cid,62,277,'gap_fill','[TOEFL Speaking] Connect these two ideas with an appropriate academic connector: ''The intervention reduced unemployment. _____ / Wages in the affected sector also increased.''','Furthermore / Moreover / In addition',NULL,'Any of these additive connectors works: ''Furthermore / Moreover / In addition'' + comma introduces a new supporting point in the same direction.','easy'),
  (cid,62,278,'gap_fill','[TOEFL Speaking] Complete using contrast connectors: ''The reading _____ (argue/present) that _____ (merit) pay improves teacher performance; _____ (however), the professor _____ (contend/present) that the evidence is _____ (inconclusive) and that _____ _____ (such/scheme) may _____ (damage) _____ _____ (professional/collaboration).','argues / merit / however / contends / inconclusive / such schemes / damage / professional collaboration',NULL,'''However'' after semicolon = formal adversative; present tense for reading (''argues'') and professor (''contends'').','medium'),
  (cid,62,279,'production','[TOEFL Speaking — 60s] Compare reading and lecture on renewable energy. The reading is optimistic; the professor raises concerns. Use at least six connectors.','',NULL,'The reading and the lecture both address the prospects for renewable energy, though they reach rather different conclusions. The reading argues that solar and wind technologies have become cost-competitive with fossil fuels and that the pace of deployment has accelerated dramatically over the past decade — evidence that the reading contends justifies optimism about the feasibility of a clean energy transition. Furthermore, the reading suggests that energy storage technologies are improving rapidly and that grid integration challenges, while real, are surmountable. The professor, by contrast, is considerably more cautious. While she acknowledges that renewable costs have fallen dramatically, she contends that the reading understates the complexity of replacing fossil fuels at the scale and reliability that modern economies require. In particular, she argues that the variability of solar and wind power creates grid management challenges that battery storage alone cannot resolve. Moreover, she suggests that the political economy of the energy transition — involving powerful incumbent interests and distributional conflicts over who bears the costs of adjustment — is considerably more difficult than the reading implies. Consequently, while she shares the reading''s ultimate goal, she contends that achieving it will require not just technology deployment but fundamental changes in market design and regulatory frameworks.','hard'),
  (cid,62,280,'gap_fill','[TOEFL Speaking] Choose the correct connector: ''The two studies reached similar conclusions _____ (despite/although/however) using different methodologies, which _____ (suggest/present) that the core finding is _____ (robust).''','despite / suggests / robust',NULL,'''Despite'' + gerund phrase (''using different methodologies'') = correct; ''although'' requires a finite clause; ''however'' is an adverb, not a conjunction.','medium'),
  (cid,62,281,'gap_fill','[TOEFL Speaking] Connect the ideas formally: ''The reform failed. _____ (reason) was inadequate funding. _____ (addition) there was a lack of political will.''','One reason / In addition,',NULL,'''One reason was'' = nominal cause explanation; ''In addition,'' = additive connector with comma before next clause.','easy'),
  (cid,62,282,'multiple_choice','[TOEFL Speaking] Which response uses academic connectors most effectively?','The reading contends that urban sprawl increases car dependency. The professor, however, argues that public transport investment can offset this effect. Furthermore, she cites evidence from European cities where density and transit have been successfully combined.','["The reading says sprawl is bad. The professor says transit is good. Also there is European evidence.","The reading contends that urban sprawl increases car dependency. The professor, however, argues that public transport investment can offset this effect. Furthermore, she cites evidence from European cities where density and transit have been successfully combined.","Urban sprawl is bad for cars. Transit is good. Europe has evidence.","The reading and professor disagree about sprawl, transit, and European cities."]','Option B: ''contends'' (RS verb), ''however'' (contrast), ''Furthermore'' (addition) + specific content = full academic connector integration.','medium'),

  -- BLOCK 63: Advanced connector patterns in TOEFL Writing (8 ex)
  (cid,63,283,'production','[TOEFL Writing — 200 words] Write a body paragraph on climate change policy using at least eight different academic connectors.','',NULL,'The governance of climate change represents one of the most complex collective action problems that the international community has ever faced — and, notwithstanding decades of negotiation, meaningful progress has remained elusive. In the first place, the distributional consequences of both mitigation and adaptation are deeply contested: those who have contributed least to the problem are often those who stand to suffer most from its consequences, yet they typically have the least capacity to respond. Furthermore, the long time horizons involved in climate change create a structural mismatch with the short-term incentives of democratic politics, in which governments are typically judged on immediate outcomes rather than on investments whose benefits materialize over decades. Consequently, even governments that accept the scientific consensus face genuine political obstacles to implementing the policies that the science implies. By contrast, those who argue that economic incentives alone — particularly carbon pricing — can drive the transition tend to underestimate the depth of the political resistance and the distributional concerns that such mechanisms generate. Nevertheless, there are grounds for cautious optimism: the dramatic cost reductions in renewable energy have altered the political economy of the transition, making it possible to frame decarbonization as an economic opportunity rather than purely a sacrifice. In other words, the conditions for progress may be improving, albeit more slowly than the science requires.','hard'),
  (cid,63,284,'gap_fill','[TOEFL Writing] _____ (In/light/of) the evidence _____ (review/passive), it _____ (appear) that neither _____ (approach) is _____ (sufficient) on its _____ (own); _____ (rather), a _____ (combination) of _____ _____ (instrument) _____ _____ _____ (will/be/require/passive) to _____ (achieve) the _____ _____ (desire/outcome).','In light of / reviewed / appears / approach / sufficient / own / rather / combination / instruments / will be required / achieve / desired outcome',NULL,'''In light of + noun phrase'' = connector introducing conclusion from evidence; ''rather'' = correction/alternative; ''will be required'' = modal passive.','hard'),
  (cid,63,285,'gap_fill','[TOEFL Writing] _____ (To/illustrate), a _____ (study) _____ (conduct/passive) in _____ (twelve) _____ _____ (country/found/that) _____ _____ (governance/reform) _____ _____ (consistently/produce) _____ (better) _____ (outcome) _____ (when) _____ (accompany/passive) by _____ _____ (civic/engagement/initiative).','To illustrate / study / conducted / twelve / countries found that / governance reform / consistently produced / better / outcomes / when / accompanied / civic engagement initiatives',NULL,'''To illustrate'' = connector introducing a specific example; ''conducted'' = participial passive modifier; ''accompanied by'' = passive with instrumental.','medium'),
  (cid,63,286,'gap_fill','[TOEFL Writing] _____ (Taken/together), these _____ (finding) _____ (suggest) that the _____ (prevailing) _____ _____ (theoretical/framework) _____ (require) _____ (substantial) _____ (revision); _____ (in/particular), its _____ (assumption) about _____ (rational) _____ _____ (actor/behavior) _____ (appear) increasingly _____ (difficult) to _____ (sustain).','Taken together / findings / suggest / prevailing / theoretical framework / requires / substantial / revision / in particular / assumptions / rational / actor behavior / appear / difficult / sustain',NULL,'''Taken together'' = synthesis connector; ''in particular'' = specification; ''actor behavior'' = compound noun; ''appear...to sustain'' = infinitive complement.','hard'),
  (cid,63,287,'gap_fill','[TOEFL Writing] The _____ (argument) _____ (develop/passive) in this essay has _____ (three) _____ _____ (main/component). _____ (First and foremost), _____ (formal) _____ (institution) _____ (matter); _____ (second), _____ _____ _____ (informal/norm/shape) how those institutions _____ (operate); _____ (third), and _____ _____ (perhaps/above/all), _____ (capacity) is _____ _____ (often/the/binding) _____ (constraint).','argument / developed / three / main components / First and foremost / formal / institutions / matter / second / informal norms shape / operate / third / perhaps above all / capacity / often the binding / constraint',NULL,'''First and foremost / second / third'' = formal enumeration; ''perhaps above all'' = emphatic climax in a list.','hard'),
  (cid,63,288,'multiple_choice','Which sentence uses ''in sum'' correctly?','In sum, the evidence suggests that institutional reform is possible but requires sustained political commitment.','["In sum, some evidence is good and some is bad for reform.","In sum, the evidence suggests that institutional reform is possible but requires sustained political commitment.","In sum of the evidence, reform is possible.","The evidence, in sum, reform is possible."]','Option B: ''In sum'' = formal summary connector beginning a sentence; followed by a balanced evaluative conclusion.','easy'),
  (cid,63,289,'gap_fill','[TOEFL Writing] _____ (Despite/the/fact/that) the _____ (intervention) was _____ (initially) _____ (resist/passive) by _____ (many) _____ _____ (stakeholder), it _____ (eventually/gain/past) _____ (broad) _____ _____ (political/support), _____ (largely/because) its _____ (benefit) _____ (become/past) _____ _____ _____ (visible/within/months).','Despite the fact that / intervention / initially / resisted / many / stakeholders / eventually gained / broad / political support / largely because / benefits / became / visible within months',NULL,'''Despite the fact that + clause'' = concessive conjunction; ''largely because'' = causal connector for explanation.','hard'),
  (cid,63,290,'production','[TOEFL Writing — 200 words] Write a body paragraph on inequality using at least six academic connectors.','',NULL,'The evidence on economic inequality presents a complex picture that resists simple interpretation. In the first place, the Gini coefficient — the most widely used measure of income inequality — has risen in most OECD countries over the past four decades, notwithstanding periods of strong economic growth that might have been expected to benefit workers across the income distribution. Furthermore, the mechanisms driving inequality are multiple and interact in ways that make attribution difficult: technological change has reduced the relative demand for routine labor, globalization has increased competition from lower-wage economies, and declining union density has weakened the bargaining power of workers at the lower end of the wage distribution. Consequently, the design of effective policy responses is considerably more complex than either the left (which emphasizes redistribution) or the right (which emphasizes growth) tends to acknowledge. Nevertheless, there is a growing consensus among economists that some combination of investment in skills and education, reform of wage-setting institutions, and more progressive taxation can mitigate the worst effects of structural inequality without significantly damaging economic dynamism. On balance, the question is not whether reducing inequality is desirable — there is strong evidence that high inequality imposes economic as well as social costs — but whether the political conditions for the necessary policy mix can be assembled.','hard'),

  -- BLOCK 64: Capstone production (10 ex)
  (cid,64,291,'production','[TOEFL Writing — 200 words] Write an introduction for a TOEFL essay on the relationship between democracy and economic development. Use academic connectors to structure your argument.','',NULL,'The relationship between democracy and economic development is one of the most extensively studied questions in comparative politics, yet consensus has proven elusive despite decades of quantitative and qualitative research. In the first place, the question is empirically contested: some cross-national studies find a positive association between democratic governance and long-run economic growth, while others find no consistent relationship, and a smaller body of work suggests that authoritarian regimes may achieve faster growth in the short to medium term under certain conditions. Furthermore, the causal direction of any relationship is difficult to establish, since economic development itself appears to increase the probability of democratic transition — a reverse causality problem that complicates the interpretation of observed correlations. Notwithstanding these methodological challenges, the question retains its practical importance, since it bears directly on the design of foreign assistance programs, the conditions attached to international lending, and the normative case for democracy promotion as an element of foreign policy. In light of these considerations, this essay will argue that while no simple causal relationship between democracy and growth can be established, democratic institutions do appear to generate distinctive economic benefits — particularly in the areas of property rights protection, constraint on arbitrary expropriation, and the provision of public goods — that justify continued attention to governance quality in development policy.','hard'),
  (cid,64,292,'gap_fill','[Final AC] Identify the connector type and correct any error: ''The study found significant results. Nevertheless, we must acknowledge certain limitations, in particular the small sample size, furthermore the lack of longitudinal data.''','Error: ''furthermore'' should be ''and'' or ''as well as'' here. Correct: ''...in particular the small sample size and the lack of longitudinal data.''',NULL,'''Furthermore'' cannot link two noun phrases within a list; use ''and'' or ''as well as.'' ''Nevertheless'' and ''in particular'' are used correctly.','hard'),
  (cid,64,293,'gap_fill','[Final AC] Complete the paragraph conclusion: _____ (Taken/together), the _____ (evidence/present/passive) in this _____ (section) _____ (lend) _____ (strong) _____ (support) to the _____ (central) _____ (thesis) of this essay — _____ (namely), that _____ (effective) _____ (governance) _____ (is) _____ (both) _____ (possible) and _____ (necessary) for _____ (sustained) _____ (development).','Taken together / evidence presented / section / lends / strong / support / central / thesis / namely / effective / governance / is / both / possible / necessary / sustained / development',NULL,'''Taken together'' = synthesis connector; ''namely'' = formal specification connector; ''lends strong support'' = singular verb agreeing with ''evidence.''','hard'),
  (cid,64,294,'multiple_choice','Which sentence MOST effectively opens a TOEFL essay body paragraph using connectors?','First and foremost, the evidence consistently shows that institutional quality — measured by rule of law, control of corruption, and government effectiveness — is one of the strongest predictors of long-run economic performance.','["The first thing is that institutions are important for economies.","Evidence shows institutions matter for economies and this is true.","First and foremost, the evidence consistently shows that institutional quality — measured by rule of law, control of corruption, and government effectiveness — is one of the strongest predictors of long-run economic performance.","In addition to other things, institutions are important for economic development."]','Option C: ''First and foremost'' (formal enumeration), specific content, precise vocabulary, complex sentence structure = TOEFL Band 5 quality.','hard'),
  (cid,64,295,'production','[TOEFL Writing — 200 words] Write a concluding paragraph on technology and employment using at least eight academic connectors.','',NULL,'In sum, the evidence reviewed in this essay suggests that the relationship between technological change and employment is neither as simple nor as straightforwardly optimistic as mainstream economic accounts have traditionally implied. In the first place, the assumption that technological displacement automatically generates compensating employment rests on historical patterns that may not generalize to a period when AI and automation can substitute for cognitive as well as physical labor. Furthermore, the distributional consequences of technological change have been highly unequal, benefiting those with high skills and capital assets while placing downward pressure on the wages of routine workers — a dynamic that, notwithstanding strong aggregate growth, has contributed to rising inequality in most developed economies. Consequently, the policy challenge is not simply to facilitate technological adoption but to ensure that its benefits are broadly shared and that its costs do not fall disproportionately on those least equipped to absorb them. By contrast, those who argue for slowing technological adoption to protect existing jobs underestimate the competitive costs of doing so and the long-run welfare gains that productivity growth makes possible. On balance, the most defensible position is one that embraces technological change while investing seriously in the education, training, and social insurance systems that allow workers to navigate it successfully. Nevertheless, achieving this balance requires political choices that go well beyond what market forces alone will deliver.','hard'),
  (cid,64,296,'gap_fill','[Final AC] Connect these ideas using three different connectors: Idea 1: Education increases earnings. Idea 2: It also improves health outcomes. Idea 3: The benefits are largest for disadvantaged groups. → ''Education _____ (increase) earnings. _____ (furthermore), it _____ (improve) health outcomes. _____ (above/all), the _____ (benefit) _____ (be) _____ (largest) for _____ (historically) _____ (disadvantaged) _____ (group).''','increases / Furthermore / improves / Above all / benefits / are / largest / historically / disadvantaged / groups',NULL,'''Furthermore'' = addition; ''Above all'' = emphatic climax; three connectors structure the argument in ascending order of importance.','medium'),
  (cid,64,297,'gap_fill','[Final AC] Rewrite to improve connector use: ''The policy worked. Also there were some problems. Despite this the government kept it.'' → ''The policy _____ (achieve) its _____ (primary) _____ (objective); _____ (nevertheless), _____ (several) _____ _____ (significant/challenge) _____ _____ (emerge/past/simultaneously). _____ (Notwithstanding) _____ (these/difficulty), _____ (the) _____ (government) _____ _____ _____ (elect/past/to/maintain) the _____ (program).''','achieved / primary / objective / nevertheless / several / significant challenges / emerged simultaneously / Notwithstanding / these difficulties / the / government / elected to maintain / program',NULL,'Rewritten with formal connectors (''nevertheless,'' ''notwithstanding'') and precise academic vocabulary replacing informal phrasing.','hard'),
  (cid,64,298,'production','[TOEFL Writing — 200 words] Write a body paragraph on globalization and inequality. Use connectors to show cause-effect, concession, and addition.','',NULL,'The relationship between globalization and inequality is one of the most contested empirical questions in contemporary economics, and the evidence is sufficiently complex that confident generalizations are difficult to sustain. In the first place, globalization has undeniably contributed to a dramatic reduction in extreme poverty at the global level, primarily through the integration of large developing economies — China and India in particular — into the world trading system. Furthermore, the diffusion of technology associated with trade openness has raised productivity and incomes in many low-income countries, contributing to what has been called a convergence of living standards between the global North and South. Notwithstanding these aggregate gains, however, the distribution of benefits within countries has been highly unequal. In developed economies, trade competition from lower-wage countries has contributed to wage stagnation and job displacement among manufacturing workers — a consequence that, as economists such as Autor have documented, has been concentrated in specific communities and has generated lasting social and political effects. Consequently, the net impact of globalization on inequality depends heavily on the level of analysis: while it has reduced inequality between countries, it has contributed to rising inequality within many developed economies, thereby generating political pressures that have fueled populist challenges to the liberal international order.','hard'),
  (cid,64,299,'gap_fill','[Final AC] Complete the essay conclusion: _____ (In/conclusion), the _____ (evidence) _____ _____ (examine/passive) in this essay _____ (point) toward a _____ (nuanced) _____ (view) — one that _____ (reject) _____ (both) _____ (extreme/noun) and _____ (insist) _____ (on/the/importance) of _____ (context). _____ (Above/all), it _____ _____ _____ _____ (suggest/that/policy/must) be _____ (adaptive), _____ _____ _____ (evidence-based), and _____ _____ (sensitive) to the _____ _____ _____ (specific/institutional/condition) in _____ (which) it _____ (operate).','In conclusion / evidence / examined / points / nuanced / view / rejects / both / extremes / insists / on the importance / context / Above all / suggests that policy must / adaptive / evidence-based / sensitive / specific institutional conditions / which / operates',NULL,'''In conclusion'' = standard formal closing connector; ''Above all'' = emphatic final point; ''evidence-based'' = compound adjective.','hard'),
  (cid,64,300,'production','[TOEFL Writing — Final capstone] Write a 200-word paragraph making a complex argument about education policy. Use at least ten different academic connectors and demonstrate mastery of concession, contrast, cause-effect, addition, and emphasis.','',NULL,'The case for substantial public investment in education rests on a convergence of arguments from economics, political philosophy, and social science that, taken together, constitute one of the strongest policy rationales available. In the first place, the economic returns to education are among the most robust findings in labor economics: both at the individual level, where additional years of schooling consistently predict higher lifetime earnings, and at the aggregate level, where human capital accumulation is associated with higher productivity growth and innovation capacity. Furthermore, education generates positive externalities — in the form of reduced crime, better health behavior, and more informed democratic participation — that the market alone would underprovide. Notwithstanding these compelling arguments, however, the design of education policy involves genuine trade-offs that cannot be wished away. In particular, the allocation of resources between early childhood intervention, primary and secondary schooling, and higher education involves difficult choices about equity and efficiency that evidence alone cannot resolve. Moreover, the quality of education matters as much as its quantity: additional years of poor-quality schooling add little to human capital, a finding that has significant implications for how education investments are designed and evaluated. Consequently, while the case for public investment in education is compelling in principle, its translation into effective policy requires institutional capacity, political commitment, and a willingness to learn from evidence that is not always easy to assemble. Above all, it requires treating education not as a cost to be minimized but as a foundational investment in human potential and democratic society.','hard')

